{
  "rule_name": "rule_city_after_argued_submitted_header",
  "file": "/mnt/data/LSF/rules/court/agentic_rule_full_data_gpt54mini/all_docs/q06_in_what_city_was_the_case_argued_or_submitted/rule_city_after_argued_submitted_header.py",
  "code": "def rule_city_after_argued_submitted_header(doc: dict) -> list[dict]:\n    try:\n        import re\n\n        lines = doc.get(\"lines\") or []\n        if not isinstance(lines, list):\n            return []\n\n        header_re = re.compile(r\"\\b(argued|submitted|resubmitted)\\b\", re.I)\n        city_re = re.compile(r\"^[A-Z][A-Za-z0-9'.-]*(?: [A-Z][A-Za-z0-9'.-]*)*, [A-Z][A-Za-z .'-]{2,}$\")\n\n        def norm_text(x):\n            return (x or \"\").strip()\n\n        for idx, line in enumerate(lines[:120]):\n            text = norm_text(line.get(\"text\"))\n            if not text or not header_re.search(text):\n                continue\n            if not re.search(r\"\\b\\d{4}\\b\", text):\n                continue\n            for nxt in lines[idx + 1 : idx + 5]:\n                nxt_text = norm_text(nxt.get(\"text\"))\n                if not nxt_text:\n                    continue\n                if city_re.match(nxt_text):\n                    out = {\"text\": nxt_text}\n                    if \"page_no\" in nxt:\n                        out[\"page_no\"] = nxt.get(\"page_no\")\n                    if \"line_no\" in nxt:\n                        out[\"line_no\"] = nxt.get(\"line_no\")\n                    return [out]\n                if \"Filed\" in nxt_text or \"Before:\" in nxt_text:\n                    break\n        return []\n    except Exception:\n        return []\n",
