{
  "rule_name": "rule_city_from_oral_argument_order_phrase",
  "file": "/mnt/data/LSF/rules/court/agentic_rule_full_data_gpt54mini/all_docs/q06_in_what_city_was_the_case_argued_or_submitted/rule_city_from_oral_argument_order_phrase.py",
  "code": "def rule_city_from_oral_argument_order_phrase(doc: dict) -> list[dict]:\n    try:\n        import re\n\n        lines = doc.get(\"lines\") or []\n        if not isinstance(lines, list):\n            return []\n\n        lines = sorted(\n            [line for line in lines if isinstance(line, dict)],\n            key=lambda x: (x.get(\"page_no\", 0), x.get(\"line_no\", 0)),\n        )\n\n        trigger_re = re.compile(\n            r\"(reschedule oral argument|oral argument to the week|submission for this case is vacated|submission is vacated)\",\n            re.I,\n        )\n        inline_city_re = re.compile(\n            r\"\\bin ([A-Z][A-Za-z0-9'.-]*(?: [A-Z][A-Za-z0-9'.-]*)*, [A-Z][A-Za-z .'-]{2,})\"\n        )\n        city_line_re = re.compile(\n            r\"^[A-Z][A-Za-z0-9'.-]*(?: [A-Z][A-Za-z0-9'.-]*)*, [A-Z][A-Za-z .'-]{2,}$\"\n        )\n\n        def clean(text: str) -> str:\n            return (text or \"\").strip().rstrip(\" .;:\")\n\n        for idx, line in enumerate(lines[:80]):\n            text = clean(line.get(\"text\", \"\"))\n            if not text or not trigger_re.search(text):\n                continue\n            m = inline_city_re.search(text)\n            if m:\n                out = {\"text\": clean(m.group(1))}\n                if \"page_no\" in line:\n                    out[\"page_no\"] = line.get(\"page_no\")\n                if \"line_no\" in line:\n                    out[\"line_no\"] = line.get(\"line_no\")\n                return [out]\n            for nxt in lines[idx + 1 : idx + 4]:\n                nxt_text = clean(nxt.get(\"text\", \"\"))\n                if city_line_re.match(nxt_text):\n                    out = {\"text\": nxt_text}\n                    if \"page_no\" in nxt:\n                        out[\"page_no\"] = nxt.get(\"page_no\")\n                    if \"line_no\" in nxt:\n                        out[\"line_no\"] = nxt.get(\"line_no\")\n                    return [out]\n        return []\n    except Exception:\n        return []\n",
